import sys


def emit_run(output: list[str], start: int, end: int) -> None:
    if end - start >= 2:
        output.append(f"{start}-{end}")
    else:
        output.append(str(start))
        if end != start:
            output.append(str(end))


def main() -> None:
    lines = sys.stdin.buffer
    count_line = lines.readline()
    if not count_line:
        return

    count = int(count_line)
    if count == 0:
        print()
        return

    start = previous = int(lines.readline())
    output: list[str] = []

    for _ in range(count - 1):
        current = int(lines.readline())
        if current == previous + 1:
            previous = current
        else:
            emit_run(output, start, previous)
            start = previous = current

    emit_run(output, start, previous)
    print(",".join(output))


if __name__ == "__main__":
    main()

