use std::fmt::Write as _;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();
    let n: usize = values.next().unwrap().parse().unwrap();

    let numbers: Vec<i64> = values
        .take(n)
        .map(|value| value.parse().unwrap())
        .collect();

    let mut output = String::new();
    let mut start = 0;

    while start < numbers.len() {
        let mut end = start;
        while end + 1 < numbers.len() && numbers[end].checked_add(1) == Some(numbers[end + 1]) {
            end += 1;
        }

        if !output.is_empty() {
            output.push(',');
        }

        if end - start + 1 >= 3 {
            write!(&mut output, "{}-{}", numbers[start], numbers[end]).unwrap();
        } else {
            write!(&mut output, "{}", numbers[start]).unwrap();
            if end > start {
                write!(&mut output, ",{}", numbers[end]).unwrap();
            }
        }

        start = end + 1;
    }

    println!("{output}");
}

